import{c as t,Q as n,j as o,m as r}from"./chunks/framework.BqPkuuVc.js";const v=JSON.parse('{"title":"Creating an event from Eventor","description":"","frontmatter":{},"headers":[],"relativePath":"user/event-setup/create-event-from-eventor.md","filePath":"user/event-setup/create-event-from-eventor.md"}'),s={name:"user/event-setup/create-event-from-eventor.md"};function a(i,e,l,h,g,d){return n(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="creating-an-event-from-eventor" tabindex="-1">Creating an event from Eventor <a class="header-anchor" href="#creating-an-event-from-eventor" aria-label="Permalink to &quot;Creating an event from Eventor&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers whose federation uses Eventor for entries.</p><p>How to create a new event by importing it directly from Eventor — classes, competitors, clubs, and start times in one step; just import course files.</p><h2 id="when-to-use-this" tabindex="-1">When to use this <a class="header-anchor" href="#when-to-use-this" aria-label="Permalink to &quot;When to use this&quot;">​</a></h2><p>Use <strong>New event → Import from Eventor…</strong> when:</p><ul><li>Your federation publishes the event on Eventor and accepts entries there.</li><li>You&#39;ve connected Eventor in <strong>Settings → Eventor</strong>.</li><li>You want classes, competitors, clubs, and (if available) start times pulled in automatically.</li></ul><p>If your event isn&#39;t on Eventor — or you only have IOF XML files — use <a href="./create-event">Create manually</a> instead and import data afterwards from <a href="./import-event-data">files</a>.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p><strong>Import from Eventor…</strong> appears as soon as <strong>Enable Eventor</strong> is switched on in <strong>Settings → Eventor</strong>. For it to do anything, configure the connection there once:</p><ul><li><strong>Host name</strong> — the URL of your Eventor instance (e.g. <code>https://eventor.orienteering.org.au</code>).</li><li><strong>API key</strong> — your Eventor API credentials.</li><li><strong>Organisation ID</strong> — your club or federation&#39;s number in Eventor. It decides which events are listed for you to import.</li><li><strong>Event history</strong> — <strong>Future only</strong> to begin with. Eventor events that have already run are listed only if you reach back here (the past week, month or six months); each extra month makes the list slower to load, so reach back only when you need an event that has already run.</li></ul><p>If the connection is switched on but incomplete, Manager tells you when you choose <strong>Import from Eventor…</strong> and points you to Settings.</p><h2 id="creating-the-event" tabindex="-1">Creating the event <a class="header-anchor" href="#creating-the-event" aria-label="Permalink to &quot;Creating the event&quot;">​</a></h2><ol><li><p>On the <strong>Events</strong> page, click <strong>New event</strong> and choose <strong>Import from Eventor…</strong>.</p></li><li><p>Manager fetches the list of upcoming events for your organisation from Eventor — this can take a moment, and it keeps looking for new ones in the background once the list is shown. Use <strong>Search events</strong> to narrow it down by name, or the <strong>Organisation</strong> filter to show one organiser&#39;s events.</p></li><li><p>Select the event you want to import. Manager reads what it is straight from Eventor and says underneath the list what it will create:</p><ul><li>An event Eventor holds as <strong>several races</strong> — a 3 Days, a two-race weekend — becomes a <a href="./multi-stage-events#from-eventor">multi-stage event</a>, one meshO event per race. There is nothing to choose here: that&#39;s the event&#39;s own shape. Multi-stage events are still experimental, so Manager shows a notice first; click <strong>Continue</strong> to go on.</li><li>Anything else is created as an ordinary event, with <strong>Create as</strong> set to <strong>Individual</strong> or <strong>Relay</strong> according to what Eventor says. Move it yourself if Eventor is wrong — it can&#39;t tell that a relay taking individual entries is a relay, so those arrive as Individual. Choosing <strong>Relay</strong> asks for the <strong>Number of legs</strong> and the <strong>Mass start time</strong>.</li></ul></li><li><p>Click <strong>Create event</strong>. Manager runs through the import in steps and shows progress for each:</p><ul><li>Fetching event details</li><li>Fetching classes</li><li>Fetching entries</li><li>Fetching start times</li><li>Importing data</li></ul></li><li><p>When the import finishes you&#39;ll see a summary:</p><ul><li><strong>Classes imported</strong></li><li><strong>Competitors imported</strong></li><li><strong>Clubs imported</strong></li><li><strong>Relay teams</strong>, for a relay</li><li><strong>Allocated start times</strong> — or <em>&quot;not yet available&quot;</em> if the draw hasn&#39;t been done on Eventor yet</li><li><strong>Warnings</strong>, if anything in Eventor&#39;s data couldn&#39;t be imported as it stood</li></ul><p>A multi-stage event lists one line per stage instead, with its classes and competitors.</p></li><li><p>Click <strong>Open event</strong> to go to the new event&#39;s dashboard — or <strong>Open</strong>, for a multi-stage event, to go to the carnival&#39;s overview. Click <strong>Close</strong> to stay on the Events page.</p></li></ol><p>The event is created in <strong>Setup</strong> mode with defaults inherited from <strong>Settings → Event defaults</strong> — same as any other new event. Only the name, date, discipline, the event&#39;s location (where Eventor gives one), classes, competitors, clubs, relay teams and start times come from Eventor.</p><p>The <strong>discipline</strong> comes from the race distance the organiser set on the Eventor event, and covers both the course lengths (Sprint, Middle, Long, Ultra Long) and the competition formats Eventor lists beside them (Knock Out Sprint, Sprint Relay, Mass Start, Pursuit, Relay, Mixed Relay, Qualification, PreO, TempO). Eventor treats Middle as its default, so an event that doesn&#39;t set a distance imports as Middle — change it in the event details if it&#39;s wrong.</p><p>The discipline is a description of the race. It doesn&#39;t make the event a relay on its own — that&#39;s the <strong>event type</strong>, which Manager derives from Eventor and shows you before the import runs.</p><h2 id="from-the-upcoming-tab-with-one-click" tabindex="-1">From the Upcoming tab, with one click <a class="header-anchor" href="#from-the-upcoming-tab-with-one-click" aria-label="Permalink to &quot;From the Upcoming tab, with one click&quot;">​</a></h2><p>With Eventor switched on, the <strong>Upcoming</strong> tab of the <strong>Events</strong> page also lists your Eventor events below your own, under <strong>Upcoming on Eventor</strong>. Until you&#39;ve said which events to list, it shows a <strong>Show your Eventor events here</strong> card with a <strong>Set up</strong> button. In <strong>Settings → Eventor</strong>, choose the <strong>Organisations</strong> whose events to show (an association brings in its clubs&#39; events too), or enter text under <strong>Event name contains</strong> — with neither, nothing is listed. <strong>Choose events</strong>, above the list, takes you back there. To hide the list, turn off <strong>Show upcoming Eventor events on the events list</strong> in the same place.</p><p>Only events with no Manager event yet are offered. Click one, or its <strong>Create event</strong> button, and Manager creates and imports it straight away, exactly as above — an individual event or a multi-race event needs no further questions. A relay, or an event Eventor doesn&#39;t say the type of, opens the <strong>New event — Eventor</strong> dialog with it selected, so you can confirm <strong>Create as</strong> and set the legs and mass start time. If the import reported anything, a <strong>Created with warnings</strong> box lists it.</p><h2 id="after-import" tabindex="-1">After import <a class="header-anchor" href="#after-import" aria-label="Permalink to &quot;After import&quot;">​</a></h2><p>The event is linked to its Eventor source. That link gives you three things:</p><ul><li><strong>Re-import later</strong> — as entries close and the start list draw is published, you can pull the latest data without searching for the event again. See <a href="./import-event-data#re-importing-from-eventor">Re-importing from Eventor</a>.</li><li><strong>Publish back to it</strong> — the linked event is pre-selected when you upload the <a href="./start-draw#uploading-the-start-list-to-eventor">start list</a> or, after the event, the results.</li><li><strong>Traceability</strong> — the link is recorded on the event so you can see where the data came from.</li></ul><p>You&#39;ll typically want to:</p><ol><li>Open the event details (<strong>Event details</strong> on the event card at the top of the dashboard) and review the name, date, and the start, finish and check codes. See <a href="./create-event#editing-event-details">Editing event details</a>.</li><li>Import courses separately — Eventor doesn&#39;t carry course definitions. Click <strong>Import</strong> on the dashboard&#39;s <strong>Event data</strong> card, and choose an IOF CourseData XML, OJSON or Purple Pen file on the <strong>Courses</strong> row. See <a href="./import-event-data#course-data-iof-coursedata-xml">Importing course data</a>.</li><li>Check the imported data: <ul><li>Open the <strong>Classes</strong> page — confirm the right classes exist (course assignment comes after importing courses).</li><li>Open the <strong>Competitors</strong> page — confirm card numbers and class assignments. Sort by card number to spot blanks.</li><li>If start times were imported, the <strong>Competitors</strong> page shows each competitor&#39;s allocated time and its source.</li></ul></li></ol><h2 id="importing-into-an-existing-event-instead" tabindex="-1">Importing into an existing event instead <a class="header-anchor" href="#importing-into-an-existing-event-instead" aria-label="Permalink to &quot;Importing into an existing event instead&quot;">​</a></h2><p>If you&#39;ve already created an event manually and want to pull Eventor data into it after the fact — use the <strong>Other event</strong> tab of the <strong>Import event data</strong> dialog, which can also link the event and take its name, date and discipline from Eventor. See <a href="./import-event-data#importing-into-an-existing-event">Importing into an existing event</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./create-event">Creating an event</a> — the standard (non-Eventor) flow</li><li><a href="./import-event-data">Importing event data</a> — IOF XML, Purple Pen, and Eventor re-imports</li><li><a href="./../reference/settings">Settings</a> — where the Eventor connection is configured</li><li><a href="./classes-and-courses">Classes and courses</a> — editing what the import created</li><li><a href="./competitors-clubs-teams">Competitors, clubs and teams</a> — editing imported competitors</li><li><a href="./start-times">Start times</a> — how imported start times interact with other sources</li><li><a href="./multi-stage-events#from-eventor">Multi-stage events</a> — what a multi-race Eventor event becomes</li></ul>',28)])])}const m=t(s,[["render",a]]);export{v as __pageData,m as default};
